def semver_sort(versions):
    def parse_version(version):
        # Split on '+' to separate build metadata
        if '+' in version:
            version_part, build_metadata = version.split('+', 1)
        else:
            version_part = version
            build_metadata = ''

        # Split on '-' to separate pre-release
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
            # Convert each identifier
            parsed_prerelease = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
        else:
            parsed_prerelease = None

        return (major, minor, patch, prerelease, parsed_prerelease)

    def compare_key(version_string):
        major, minor, patch, prerelease, parsed_prerelease = parse_version(version_string)

        # Create sort key
        # Versions with pre-release sort before versions without
        if parsed_prerelease is not None:
            # Has pre-release: sort before same version without pre-release
            return (major, minor, patch, 0, parsed_prerelease)
        else:
            # No pre-release: sort after same version with pre-release
            return (major, minor, patch, 1, [])

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

